    const w = d.collapsed ? '0px' : d.width + 'px';
    stage.style.setProperty('--css-tuner-left', d.side === 'left' ? w : '0px');
    stage.style.setProperty('--css-tuner-right', d.side === 'right' ? w : '0px');
